// ===== Бодит мэдээнүүд (2026-11-20) — өдөр бүр шинэчлэгдэнэ =====
const ARTICLES = [
  {id:1, cat:"uls-tor", title:"УИХ Ерөнхийлөгч У.Хүрэлсүхийг 92.3 хувийн саналаар үүрэгт ажлаас нь чөлөөлөв", titleEn:"Parliament relieves President Khurelsukh of duties by 92.3 percent vote", time:"15 мин", timeEn:"15 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Mongolian%20Government%20Palace%20and%20Tamgha%20statue.jpg?width=1000", text:"Улсын Их Хурлын чуулганы өчигдөр буюу арваннэгдүгээр сарын 19-ний нэгдсэн хуралдаанаар Монгол Улсын Ерөнхийлөгч У.Хүрэлсүхийн үүрэгт ажлаасаа чөлөөлөгдөх хүсэлтийг хэлэлцэж, хуралдаанд оролцсон 104 гишүүний 92.3 хувь нь дэмжлээ. Ингэснээр зургаа дахь Ерөнхийлөгчийн бүрэн эрхийн хугацаа дуусгавар болж, Монголын түүхэнд төрийн тэргүүн өөрийн хүсэлтээр албан тушаалаа өгсөн анхны тохиолдол болов.\n\nЕрөнхийлөгч У.Хүрэлсүх энэ сарын 17-нд мэдэгдэл хийж, өөрт нь тулгараад буй авлигын хэргийн талаарх гүтгэлэг худал болохыг нотлохын тулд албан тушаалаа өгч, жирийн иргэний хувиар шалгуулна гэж мэдэгдсэн юм. Уг хэрэг нь 2019 онд түүнийг Ерөнхий сайдаар ажиллаж байх үед Тавантолгой-Гашуунсухайт чиглэлийн 234 км төмөр зам барих гэрээг тендер зарлалгүйгээр «Боди Интернэшнл» компанид олгосонтой холбоотой бөгөөд Улаанбаатар хотын дарга асан Х.Нямбаатар төмөр замын урьдчилгаа төлбөрөөс 110 сая ам.доллар улс төрчдөд хахууль болон очсон, үүний 25 сая ам.долларыг нь Хүрэлсүх авсан гэж мэдэгдсэн байна. Ерөнхийлөгч үүнийг эрс няцаажээ.\n\nЧуулганы хуралдаанд Ерөнхийлөгч өөрөө үг хэлж, «Төрийн тэргүүний нэр төр бол бүрэн эрхт тусгаар улсын нэр хүнд, Монгол төрийн дархлаа, манай ард түмний эв нэгдэлтэй салшгүй холбоотой эрхэм зүйл» гэж онцолсон байна. Гишүүд асуулт асууж, үг хэлсний дараа санал хураалт явуулсан бөгөөд Ерөнхий сайд Н.Учрал бүх ард түмнээс сонгогдсон Ерөнхийлөгч өөрийн хүсэлтээр чөлөөлөгдөж байгаад харамсалтай байна гэж мэдэгдлээ.\n\nДараагийн Ерөнхийлөгч сонгогдтол УИХ-ын дарга С.Бямбацогт Ерөнхийлөгчийн бүрэн эрхийг түр хэрэгжүүлнэ. Хуульд зааснаар ээлжит бус сонгуулийг дөрвөн сарын дотор зарлан явуулах бөгөөд сонгуулийн товыг ирэх арванхоёрдугаар сарын 20-ны дотор гаргах хүлээлттэй байна. Хүрэлсүх 2021 оны зургаадугаар сарын 25-нд тангараг өргөж, Ерөнхийлөгчөөр сонгогдсон бөгөөд түүний бүрэн эрхийн хугацаа 2027 онд дуусах байсан юм.", textEn:"At its plenary session yesterday, November 19, the State Great Khural discussed President U. Khurelsukh's request to be relieved of his duties, and 92.3 percent of the 104 members present supported it. The sixth President's term has now ended, making this the first time in Mongolia's history that a head of state has voluntarily stepped down.\n\nOn November 17, President Khurelsukh said he would give up his post and submit to investigation as an ordinary citizen in order to prove that the corruption allegations against him are false. The case concerns a contract awarded in 2019, when he was prime minister, to build the 234-kilometre Tavantolgoi-Gashuunsukhait railway without a tender, to the company Bodi International. Former Ulaanbaatar mayor Kh. Nyambaatar has said that 110 million US dollars from the railway's advance payment went to politicians as kickbacks, including 25 million dollars to Khurelsukh. The President has strongly denied this.\n\nSpeaking at the session, the President said: «The honour of the head of state is a precious thing, inseparably linked to the reputation of a sovereign independent state, the immunity of the Mongolian state and the unity of our people.» After members asked questions and spoke, the vote was held, and Prime Minister N. Uchral said it was regrettable that a President elected by the whole people was stepping down at his own request.\n\nUntil the next President is elected, Parliament Speaker S. Byambatsogt will exercise presidential powers on an interim basis. By law, an extraordinary election must be called within four months, and the election date is expected to be set by December 20. Khurelsukh was sworn in as President on June 25, 2021, and his term would have run until 2027."},
  {id:2, cat:"uls-tor", title:"Чөлөөлөгдсөн Ерөнхийлөгч насан туршийн сул цалин авч, гурван жил тусгай хамгаалалтад байна", titleEn:"Relieved president to receive lifetime salary and three years of special protection", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Mongolian%20parliament%20members.jpg?width=760", text:"Монгол Улсын Ерөнхийлөгчийн тухай хуульд зааснаар төрийн тэргүүний бүрэн эрх дуусгавар болсон тохиолдолд түүнд насан туршийн сул цалин олгож, гурван жилийн хугацаанд төрийн тусгай хамгаалалт болон бусад хангамж эдлүүлэх зохицуулалт үйлчилдэг. Сул цалин нь Засгийн газрын гишүүний тухайн үеийн цалинтай тэнцэх хэмжээтэй байх бөгөөд энэ талаар тусгайлан шийдвэр гаргах шаардлагагүй гэж хуульд заажээ.\n\nМөн чөлөөлөгдсөн Ерөнхийлөгч гурван жилийн хугацаанд суудлын автомашин болон холбоогоор үйлчлүүлж, төрийн тусгай хамгаалалтад байх юм. УИХ-ын чуулган өчигдөр түүний чөлөөлөгдөх хүсэлтийг 92.3 хувийн саналаар дэмжсэнээр бүрэн эрхийн хугацаа нь дуусгавар болсон бөгөөд дээрх баталгаа нь хуулийн дагуу шууд хэрэгжих эрх зүйн зохицуулалттай байна.\n\nХүрэлсүх 2021 онд Монгол Улсын зургаа дахь Ерөнхийлөгчөөр сонгогдож, мөн оны зургаадугаар сарын 25-нд тангаргаа өргөсөн юм. Тэрбээр өмнө нь Ерөнхий сайд, УИХ-ын гишүүн, Шадар сайд зэрэг өндөр албан тушаал хашиж байсан бөгөөд энэ удаад өөрийн хүсэлтээр дөрөв дэх удаагаа өндөр албан тушаалаас чөлөөлөгдөж байна.", textEn:"Under Mongolia's Law on the President, when a head of state's term ends, the former president receives a lifetime salary and enjoys state special protection and other benefits for three years. The salary is set at the level of a Cabinet minister's salary at the time, and the law says no separate decision is needed for it to apply.\n\nThe relieved President will also have the use of a car and communications services and remain under state special protection for three years. Parliament backed his request to step down yesterday by 92.3 percent, ending his term, and these guarantees now apply directly under the law.\n\nKhurelsukh was elected as Mongolia's sixth President in 2021 and was sworn in on June 25 of that year. He previously held senior posts including Prime Minister, member of parliament and Deputy Prime Minister, and this is the fourth time he has left a senior post at his own request."},
  {id:3, cat:"ediin-zasag", title:"Шатахууны үнэ буурлаа: АИ-92 150, «Евро» АИ-92 1000 төгрөгөөр хямдарсан нь өнөөдрөөс хэрэгжиж байна", titleEn:"Fuel prices fall: AI-92 down 150 tugriks, Euro AI-92 down 1,000 from today", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Bishkek%2003-2016%20img21%20Akhunbaev%20Street%20petrol%20station.jpg?width=760", text:"Засгийн газрын арваннэгдүгээр сарын 18-нд болсон ээлжит хуралдаанаар гаргасан шатахууны үнийг бууруулах шийдвэр өнөөдрөөс хэрэгжиж эхэллээ. Арваннэгдүгээр сарын 18-наас 19-нд шилжих шөнөөс эхлэн энгийн АИ-92 автобензиний литрийн үнэ 150 төгрөгөөр, «Евро-3» болон түүнээс дээш стандартын АИ-92-ынх 1000 хүртэл төгрөгөөр буурсан байна.\n\nАж үйлдвэр, эрдэс баялгийн сайд Г.Дамдинням үнийн бууралтыг он дуустал, цаашлаад ирэх оны нэгдүгээр сараас гуравдугаар сар хүртэл үргэлжлүүлэх төлөвлөгөөтэй гэж мэдэгдлээ. Түүний хэлснээр нийт шатахууны 20-30 орчим хувийг евро-5, бусад хэсгийг евро-2 төрлөөр авч байгаа бөгөөд дэлхийн зах зээл дээр ирэх саруудад шатахууны үнэ буурна гэсэн хүлээлт байгаа нь энэ шийдвэрт нөлөөлсөн байна.\n\nУлаанбаатар хотын хэмжээнд 270 шатахуун түгээх станц үйл ажиллагаа явуулдаг бөгөөд эдгээрээс 204 нь хэвийн ажиллаж байна. Хотод үүсээд байсан шатахууны хомсдол, дарааллын асуудал одоогоор хэвийн хэмжээнд очсон гэж Шатахууны шуурхай штабаас мэдээллээ. Мөн аж ахуйн нэгжүүдэд Хөгжлийн банкаар дамжуулан 7 хувийн хүүтэй хөнгөлөлттэй зээл олгож, нөөц бүрдүүлэх чиглэлээр санхүүжилт гаргах юм.\n\nСалбарын мэдээллээр АИ-92 бензиний үнэ өмнө нь 2590 төгрөгөөс 3600 төгрөг болж, 39 орчим хувиар өссөн бол импортын худалдан авах үнэ тонн тутамд 705 ам.доллараас 1070 ам.долларт хүрсэн байна. Засгийн газар «Евро-3» болон түүнээс дээш стандартын бензиний жижиглэнгийн үнийг хилийн үнэтэй уялдуулан бууруулах тогтоолыг шатахууны жижиглэн худалдаа эрхлэгчидтэй хамтран хэрэгжүүлж байгаа юм.", textEn:"The Cabinet's decision of November 18 to cut fuel prices takes effect today. From the night of November 18-19, the price of regular AI-92 petrol falls by 150 tugriks a litre, and Euro-3 and higher standard AI-92 by up to 1,000 tugriks a litre.\n\nMinister of Industry and Mineral Resources G. Damdinnyam said the price cut is planned to continue through the end of the year and into January-March next year. He said about 20-30 percent of fuel is Euro-5 grade and the rest Euro-2, and expectations that world fuel prices will fall in the coming months influenced the decision.\n\nOf the 270 petrol stations operating in Ulaanbaatar, 204 are working normally. The fuel shortage and queues that had built up in the capital have now returned to normal levels, the fuel emergency headquarters said. Concessional loans at 7 percent interest will also be channelled through the Development Bank to businesses to build up reserves.\n\nAccording to industry sources, the price of AI-92 petrol had earlier risen from 2,590 to 3,600 tugriks, about 39 percent, while the import purchase price rose from 705 to 1,070 US dollars a tonne. The Government is implementing its resolution to align the retail price of Euro-3 and higher petrol with the border price, in cooperation with fuel retailers."},
  {id:4, cat:"ediin-zasag", title:"Инфляц 13.4 хувьд хүрэв: хэрэглээний бараа, үйлчилгээний үнэ эхний 10 сард 13.4 хувиар өсжээ", titleEn:"Inflation hits 13.4 percent as consumer prices rise in first 10 months", time:"45 мин", timeEn:"45 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Mongolian%201000%20tugrik%20banknote.jpg?width=760", text:"Монгол Улсын нийгэм, эдийн засгийн 2026 оны эхний 10 сарын голлох үзүүлэлтүүдийг Үндэсний статистикийн хорооноос арваннэгдүгээр сарын 17-нд танилцууллаа. Хэрэглээний бараа, үйлчилгээний үнэ улсын хэмжээнд өмнөх оны мөн үеэс 13.4 хувиар өссөн байна.\n\nИнфляцад хүнсний бараа, ундаа, усны бүлгийн үнийн өсөлт хамгийн их нөлөөлсөн бөгөөд тус бүлгийн үнэ 19.8 хувиар өссөн байна. Мөн зочид буудал, нийтийн хоол, дотуур байрны үйлчилгээний үнэ 19.8 хувь, тээврийн бүлгийн үнэ 19.3 хувь, согтууруулах ундаа, тамхины үнэ 16.5 хувиар нэмэгджээ. Боловсролын үйлчилгээний үнэ 17.7 хувь, даатгал, санхүүгийн үйлчилгээ 17.1 хувиар өссөн байна.\n\nХарин орон сууц, ус, цахилгаан, түлшний бүлгийн үнэ 5.9 хувь, амралт, чөлөөт цаг, соёлын бараа, үйлчилгээний үнэ 8.4 хувь, холбооны хэрэгсэл, шуудангийн үйлчилгээний үнэ 1.2 хувиар тус тус нэмэгдсэн үзүүлэлттэй гарчээ. Барааны бүлгийн үнэ 14.3 хувь, үйлчилгээний бүлгийн үнэ 11.1 хувиар өссөн байна.\n\nҮүний зэрэгцээ Монгол Улсын гадаад худалдааны нийт бараа эргэлт 2026 оны эхний 10 сарын байдлаар өмнөх оны мөн үеэс өссөн үзүүлэлттэй гарсан байна. Хүнсний үнийн өсөлт нь өрхийн төсөвт хамгийн их дарамт үзүүлж байгаа бөгөөд Засгийн газар үнийн өсөлтийг сааруулах арга хэмжээ авах шаардлагатай байгаа талаар эдийн засагчид тэмдэглэж байна.", textEn:"The National Statistics Office presented Mongolia's key socio-economic indicators for the first 10 months of 2026 on November 17. Consumer goods and services prices rose by 13.4 percent nationwide compared with the same period last year.\n\nFood, drinks and water contributed most to inflation, with prices in that group up 19.8 percent. Hotel, restaurant and dormitory services also rose 19.8 percent, transport 19.3 percent and alcoholic drinks and tobacco 16.5 percent. Education services rose 17.7 percent and insurance and financial services 17.1 percent.\n\nHousing, water, electricity and fuel rose 5.9 percent, recreation, leisure and cultural goods and services 8.4 percent, and communications and postal services 1.2 percent. Goods prices rose 14.3 percent and services prices 11.1 percent.\n\nAt the same time, Mongolia's total foreign trade turnover in the first 10 months of 2026 was up on the same period last year. Rising food prices are putting the greatest pressure on household budgets, and economists say the Government needs measures to slow price growth."},
  {id:5, cat:"niigem", title:"Монгол Улсын Улаан дансыг 19 жилийн дараа шинэчлэн үнэлэв", titleEn:"Mongolia updates its Red List after 19 years", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Snow%20Leopard%20of%20Tost%20Mountain.png?width=760", text:"Монгол Улс хөхтөн, хэвлээр явагч, хоёр нутагтан, загас гэсэн дөрвөн том бүлгийн хүрээнд Олон улсын байгаль хамгаалах холбооны Улаан дансны улсын хэмжээний хоёр дахь иж бүрэн дахин үнэлгээг 19 жилийн дараа хийж гүйцэтгэлээ. Энэ нь зэрлэг амьтдын талаарх шинжлэх ухааны суурь мэдээллийг сайжруулах, нэн ховордсон зүйлийн хууль эрх зүйн хамгаалалтыг сайжруулахад чухал ач холбогдолтой үйл явдал боллоо.\n\nДахин үнэлгээг Дэлхийн байгаль хамгаалах сангийн Монгол дахь хөтөлбөрийн газар Байгаль орчин, уур амьсгалын өөрчлөлтийн яам, Монгол Улсын Их Сургууль, үндэсний судлаачид болон хараат бус шинжээчидтэй хамтран хийсэн юм. Өмнө нь улсын хэмжээний Улаан дансны үнэлгээг 2006 онд хийж байсан бөгөөд түүнээс хойш иж бүрэн дахин үнэлгээ хийгдээгүй тул хамгааллын статусын үнэлгээнд зөрүү, алдаа нэмэгдэх хандлагатай болоод байсан билээ.\n\nЭнэ удаад Монгол Улс нийт 249 зүйлийг дахин үнэлжээ. Үүнээс 141 нь хөхтөн зүйл (2006 онд 128 байсан), 76 нь загасны зүйл (2006 онд 64 байсан), 7 нь хоёр нутагтан зүйл (2006 онд 6 байсан), 25 нь хэвлээр явагч зүйл (2006 онд 21 байсан) байна.\n\nҮнэлгээний үр дүн нь Монгол Улсын «Амьтны тухай хууль»-ийн удахгүй хийгдэх шинэчилсэн найруулгын шинжлэх ухааны үндсэн суурь баримт бичиг болох юм. Цоохор ирвэс, хавтгай зэрэг нэн ховордсон зүйлийн хамгааллын статус, тархац, тоо толгойн талаарх шинэчилсэн мэдээлэл нь байгаль хамгаалах бодлого, арга хэмжээг илүү оновчтой төлөвлөхөд туслах төлөвтэй байна.", textEn:"Mongolia has completed the second comprehensive national reassessment of the International Union for Conservation of Nature's Red List, covering four major groups — mammals, reptiles, amphibians and fish — 19 years after the first. The work is an important step in improving the scientific basis for knowledge of wild animals and strengthening legal protection for the most endangered species.\n\nThe reassessment was carried out jointly by WWF Mongolia, the Ministry of Environment and Climate Change, the National University of Mongolia, national researchers and independent experts. The previous national Red List assessment was done in 2006, and with no comprehensive reassessment since, discrepancies and errors in conservation status assessments had been growing.\n\nThis time, Mongolia reassessed 249 species: 141 mammals (128 in 2006), 76 fish (64), 7 amphibians (6) and 25 reptiles (21).\n\nThe results will form the core scientific basis for the forthcoming revised edition of Mongolia's Law on Animals. Updated information on the conservation status, range and numbers of highly endangered species such as the snow leopard and the beaver is expected to help plan conservation policy and measures more effectively."},
  {id:6, cat:"niigem", title:"Өнөөдөр зүүн аймгуудад цас орж, шуурна; Улаанбаатарт шөнөдөө 14 хэм хүйтэн байна", titleEn:"Snow and blizzards in eastern aimags today; minus 14 in Ulaanbaatar overnight", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/1600%20block%20of%2021st%20Street%2C%20N.W.%20-%20Blizzard%20of%202010.JPG?width=760", text:"Цаг уур, орчны шинжилгээний газраас цаг агаарын урьдчилсан мэдээг шинэчлэн гаргалаа. Өнөөдөр буюу арваннэгдүгээр сарын 20-нд Сэлэнгийн зүүн, Хэнтий, Дорнод, Сүхбаатарын зарим сумдын нутгаар 0.0-2.0 миллиметр цас орж, цасан шуурга шуурах төлөвтэй байна. Салхи нутгийн зүүн хэсгээр секундэд 14-16 метр хүрч ширүүснэ.\n\nЦас, шуурганы улмаас зам, даваа, гүвээнд үзэгдэх орчин хязгаарлагдаж, халтиргаа гулгаа, мөстөлт үүсэх эрсдэлтэй байна. Малчид, иргэд, тээвэрчдэд хол замд гарахдаа онцгой анхаарал болгоомжтой байхыг цаг уурын байгууллагаас анхааруулж байна.\n\nУлаанбаатар хот орчмоор өнөөдөр үүлшинэ, ялимгүй цас орно. Салхи баруун хойноос секундэд 5-10 метр, шөнөдөө 14-16 хэм, өдөртөө 6-8 хэм хүйтэн байна. Ойрын өдрүүдэд ихэнх нутгаар хүйтний эрч чангарч, зам, даваа, гүвээнд халтиргаа гулгаа, мөстөлттэй байхыг анхааруулж байна.\n\nАрваннэгдүгээр сарын 22-нд Хөвсгөл, Сэлэнгэ, Булганы ихэнх нутаг, Төв болон Хэнтийн хойд сумдын нутгаар 0.1-2.0 миллиметр цас орж, цасан шуурга шуурах төлөвтэй байгаа бол 23-нд Сэлэнгийн зүүн, Хэнтий, Дорнодын хойд, Төв аймаг, Сүхбаатарын зарим сумдын нутгаар мөн цас орох төлөвтэй байна. Иргэд цаг агаарын мэдээг тогтмол авч, шаардлагатай үед хол замд гарахаас татгалзахыг зөвлөж байна.", textEn:"The National Agency for Meteorology and Environmental Monitoring has issued an updated weather forecast. Today, November 20, snow of 0.0-2.0 millimetres and blizzards are expected in eastern Selenge and some soums of Khentii, Dornod and Sukhbaatar. Winds will strengthen to 14-16 metres per second in the eastern part of the country.\n\nSnow and blizzards may limit visibility on roads, passes and hills, with slippery conditions and icing. Herders, residents and drivers are urged to take particular care before long journeys.\n\nAround Ulaanbaatar today it will be mostly cloudy with slight snow. Winds from the north-west at 5-10 metres per second; minus 14-16 degrees overnight and minus 6-8 during the day. In the coming days most of the country will get colder, with slippery conditions and icing on roads, passes and hills.\n\nOn November 22, snow of 0.1-2.0 millimetres and blizzards are expected across most of Khuvsgul, Selenge and Bulgan and in northern soums of Tuv and Khentii, and on November 23 in eastern Selenge, Khentii, northern Dornod, Tuv and some soums of Sukhbaatar. Residents are advised to follow weather updates regularly and to avoid long journeys when necessary."},
  {id:7, cat:"oron-nutag", title:"ДОРНОД: Өнөөдөр цас орж, шуурна — Чойбалсанд -9 хэм, салхи ширүүсч байна", titleEn:"DORNOD: Snow and blizzards today; minus 9 in Choibalsan as winds strengthen", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Mong%20winter1%20-%20panoramio.jpg?width=760", text:"Дорнод аймгийн нутгаар өнөөдөр буюу арваннэгдүгээр сарын 20-нд цас орж, цасан шуурга шуурах төлөвтэй байгааг Цаг уур, орчны шинжилгээний газраас анхаарууллаа. Аймгийн зарим сумдын нутгаар 0.0-2.0 миллиметр цас орох бөгөөд салхи секундэд 14-16 метр хүрч ширүүснэ.\n\nАймгийн төв Чойбалсан хотод өнөө өглөө үүлэрхэг, -9 хэм хүйтэн, салхи баруун хойноос секундэд 4 метр орчим, үе үе 7 метр хүрч ширүүсч байна. Өдөртөө -5 хэм хүртэл дулаарч, шөнөдөө -16 хэм хүртэл хүйтрэх төлөвтэй байна. Маргааш буюу арваннэгдүгээр сарын 21-нд өдөртөө -2 хэм, шөнөдөө -8 хэм байх төлөвтэй байна.\n\nЦас, шуурганы улмаас зам, даваа, гүвээнд үзэгдэх орчин хязгаарлагдаж, халтиргаа гулгаа, мөстөлт үүсэх эрсдэлтэй байна. Дорнод нь Монгол орны зүүн хязгаарын өргөн уудам тал нутаг бөгөөд малчид, тээвэрчид хол замд гарахдаа хурдаа тохируулж, замын нөхцөл байдлыг урьдчилан шалгахыг зөвлөж байна.\n\nЦаг уурын байгууллагын мэдээлснээр өчигдөр буюу арваннэгдүгээр сарын 19-нд Дорнодын зарим сумдын нутгаар мөн бага хэмжээний цас орж, зөөлөн цасан шуурга шуурсан байна. Иргэд цаг агаарын мэдээг тогтмол авч, шаардлагатай үед хол замд гарахаас татгалзахыг анхааруулж байна.", textEn:"The National Agency for Meteorology and Environmental Monitoring has warned that snow and blizzards are expected in Dornod aimag today, November 20. Snow of 0.0-2.0 millimetres is expected in some soums of the aimag, with winds strengthening to 14-16 metres per second.\n\nIn the aimag centre, Choibalsan, it is cloudy this morning at minus 9 degrees, with north-westerly winds of about 4 metres per second, gusting to 7 metres per second at times. It is expected to warm to minus 5 degrees during the day and fall to minus 16 overnight. Tomorrow, November 21, the daytime high will be minus 2 degrees and the overnight low minus 8.\n\nSnow and blizzards may limit visibility on roads, passes and hills, with slippery conditions and icing. Dornod is the wide steppe of Mongolia's far east, and herders and drivers are advised to adjust their speed and check road conditions in advance before long journeys.\n\nAccording to the weather agency, light snow also fell in some soums of Dornod yesterday, November 19, with light blizzards. Residents are advised to follow weather updates regularly and to avoid long journeys when necessary.", region:"dornod"},
  {id:8, cat:"delhii", title:"Трамп, Си Жиньпин, Путин нар Шэньжэньд «Энх тайвны тунхаглал» гаргав", titleEn:"Trump, Xi and Putin issue 'Declaration Towards Peace' in Shenzhen", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline%20in%20Shenzhen%20%2820250327%29.jpg?width=760", text:"АНУ-ын Ерөнхийлөгч Дональд Трамп, БНХАУ-ын дарга Си Жиньпин, ОХУ-ын Ерөнхийлөгч Владимир Путин нар өчигдөр буюу арваннэгдүгээр сарын 19-нд Хятадын Шэньжэнь хотод түүхэнд анх удаа гурван талт уулзалт хийж, «Энх тайвны төлөөх тунхаглал» гаргалаа. Уулзалт нь Ази, Номхон далайн эдийн засгийн хамтын ажиллагааны буюу АПЕК-ийн дээд хэмжээний уулзалтын хажуугаар болж, Килинь вилла хэмээх цэцэрлэгт хүрээлэн дунд орших байранд 90 орчим минут үргэлжилсэн байна.\n\nГурван удирдагч тунхаглалдаа Нэгдсэн Үндэстний Байгууллагыг шинэчлэх, газрын тосны боловсруулсан бүтээгдэхүүний үйлдвэрлэл, нийлүүлэлтийг нэмэгдүүлэх, Олон улсын эрүүгийн шүүхийн хүрээг хязгаарлах, цөмийн эрсдэлийг бууруулах талаар яриа хэлэлцээ хийх гэсэн дөрвөн амлалт өгчээ. «Цөмийн дайнд ялах боломжгүй, тиймээс хэзээ ч эхлүүлж болохгүй» гэж тунхаглалд тэмдэглэсэн байна.\n\nГэсэн хэдий ч тунхаглалд Украинд хийж буй Оросын дайн, Ираны дайн зэрэг хоёр томоохон мөргөлдөөний талаар дурдагдаагүй бөгөөд ямар ч тодорхой хугацаа, тоон зорилт тавигдаагүй байна. Трамп уулзалтын өмнө хоёр удирдагчтай тусдаа хийсэн хоёр талт уулзалтаараа Украины асуудлыг хөндсөн гэж мэдэгдсэн ч тохиролцоонд хүрэх хүлээлт бага байсан юм. Шинжээчид уулзалтыг агуулгаас илүү бэлгэдлийн шинжтэй гэж дүгнэж байна.\n\nОрос, АНУ-ын хоорондын цөмийн зэвсгийг хорогдуулах тухай сүүлчийн гэрээ болох «Шинэ START» гэрээ хоёрдугаар сард дуусгавар болсон бөгөөд Трамп Хятадыг хамруулсан «шинэ, сайжруулсан, шинэчилсэн» гэрээ байгуулахыг хүсч байгаагаа мэдэгдсэн юм. Трамп, Си хоёр энэ оны арванхоёрдугаар сард Флоридад болох «Их 20»-ийн дээд хэмжээний уулзалтаар дахин уулзах төлөвтэй байна.", textEn:"US President Donald Trump, Chinese President Xi Jinping and Russian President Vladimir Putin held the first-ever trilateral meeting yesterday, November 19, in Shenzhen, China, and issued a «Declaration Towards Peace». The meeting took place on the sidelines of the Asia-Pacific Economic Cooperation summit and lasted about 90 minutes at Kylin Villa, a residence set amid gardens.\n\nIn the declaration, the three leaders made four commitments: to reform the United Nations, to increase production and supply of refined petroleum products, to limit the reach of the International Criminal Court, and to hold talks on reducing nuclear risks. «A nuclear war cannot be won and must never be fought,» the declaration says.\n\nHowever, the declaration makes no mention of the two major wars — Russia's war in Ukraine and the war involving Iran — and sets no specific timetable or numerical targets. Trump said he raised Ukraine in separate bilateral meetings with both leaders before the three-way session, but expectations of any agreement were low. Analysts describe the meeting as heavier in symbolism than substance.\n\nThe last nuclear arms pact between Russia and the United States, known as New START, expired in February, and Trump has said he wants a «new, improved and modernized» deal that includes China. Trump and Xi are expected to meet again at the G20 summit in Florida in December."},
  {id:9, cat:"delhii", title:"Трамп: Ираны дайн «ямар нэг байдлаар» дуусна, удаан хугацааны гэрээ хэрэгтэй", titleEn:"Trump: Iran war will end 'one way or the other', lasting deal needed", time:"45 мин", timeEn:"45 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Khalig-fars-Persian-Gulf%2001.jpg?width=760", text:"АНУ-ын Ерөнхийлөгч Дональд Трамп Ираны дайныг зогсоохын тулд удаан хугацааны гэрээ хэрэгтэй гэж мэдэгдэж, мөргөлдөөн «ямар нэг байдлаар» дуусна гэж хэллээ. Түүний мэдэгдэл нь Персийн булангийн орнууд Ираны дроны довтолгоог няцааж, АНУ Ираны Кешм арал дахь пуужин хөөргөх байгууламж руу цохилт өгсний дараа гарсан байна.\n\nДайн нь хоёрдугаар сарын 28-нд АНУ, Израилийн Иран руу хийсэн цохилтоор эхэлсэн бөгөөд есөн сар үргэлжилж байна. Иран хариуд нь АНУ-ын цэргийн бааз байрладаг Персийн булангийн баян холбоотнууд руу цохилт өгч, дайны өмнө дэлхийн нефтийн дөрөвний нэгийг тээвэрлэж байсан Хормузын хоолойг хаасан байна.\n\nЛхагва гарагт Кувейт есдүгээр сараас хойших анхны Ираны довтолгоог няцааж, Бахрейн энэ долоо хоногт гурав дахь удаагаа довтолгоонд өртсөн байна. Саудын Арабаар удирдуулсан эвсэл Хуси бүлэглэлийн Эр-Рияд чиглэсэн далавчит пуужинг устгасан гэж мэдэгдлээ. АНУ-ын Төрийн департамент Саудын Араб, Бахрейн дахь иргэддээ аюулгүй байдлын сэрэмжлүүлгийг дахин гаргасан байна.\n\nҮүний зэрэгцээ Катар, Оман улс Тегерантай зуучлалын хэлэлцээ хийж байгаа бөгөөд агаарын тээврийн компаниуд Саудын чиглэлийн нислэгээ цуцлах хугацаагаа сунгасан байна. Мөргөлдөөн ширүүсч байгаа ч дайныг зогсоох дипломат оролдлого үргэлжилж байгаа юм.", textEn:"US President Donald Trump has said a lasting deal is needed to end the war with Iran, adding that the conflict will end «one way or the other». His remarks came after Gulf states repelled Iranian drone attacks and the United States struck a missile launch site on Iran's Qeshm Island.\n\nThe war began on February 28 with US and Israeli strikes on Iran and has now lasted nine months. In response, Iran has struck America's wealthy Gulf allies, which host US military bases, and blockaded the Strait of Hormuz, which carried a quarter of global oil flows before the war.\n\nOn Wednesday, Kuwait repelled the first Iranian attack since September, and Bahrain came under attack for the third time this week. The Saudi-led coalition said it had destroyed a Houthi cruise missile headed for Riyadh. The US State Department reissued security warnings to American citizens in Saudi Arabia and Bahrain.\n\nAt the same time, Qatar and Oman are pursuing mediation talks with Tehran, and airlines have extended suspensions on Saudi routes. Although fighting is intensifying, diplomatic efforts to end the war continue."},
  {id:10, cat:"delhii", title:"Хормузын хоолойд танкер үл мэдэгдэх зүйлсийн цохилтод өртөв", titleEn:"Tanker hit by unknown projectile in Strait of Hormuz", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Oil%20tanker%2C%20gas%20tanker%20in%20the%20high%20sea%20Refinery%20Industry%20cargo%20ship%20%2852848038105%29.jpg?width=760", text:"Хормузын хоолойгоор гарч явсан танкер үл мэдэгдэх зүйлсийн цохилтод өртөж, хөдөлгүүрийн өрөөнд нь гэмтэл учирсан тухай Их Британийн далайн худалдааны үйл ажиллагааны байгууллага мэдээллээ. Хэрэг явдал арваннэгдүгээр сарын 18-ны орой Оманы Хасаб хотоос хойд зүгт 6 далайн милийн зайд, 16:45 цагт /UTC/ болсон байна.\n\nМэдээлэлд танкерийн нэр, зүйлсийн гарал үүсэл, хэн хариуцах талаар дурдагдаагүй бөгөөд энэ нь өмнөх довтолгоонуудтай холбоотой эсэх нь тодорхойгүй байна. Тус байгууллага далайн тээвэрчдэд аюулгүй байдлын сэрэмжлүүлэг гаргасан байна.\n\nЭнэ хэрэг явдал нь Персийн булангийн бүс нутагт мөргөлдөөн ширүүсч байгаа үед гарсан юм. АНУ Ираны Кешм арал дахь пуужин хөөргөх байгууламж руу цохилт өгсний дараа Иран Кувейт, Бахрейн дахь АНУ-ын баазууд руу дроны довтолгоо хийж, Хуси бүлэглэл Саудын Араб руу пуужин харвасан байна.\n\nИран дайны эхэн үеэс Хормузын хоолойг хааж, тус хоолойгоор дамжин өнгөрдөг танкеруудыг онилж байгаа бөгөөд дайны өмнө тус хоолойгоор дэлхийн нефтийн дөрөвний нэг нь тээвэрлэгдэж байсан юм. Бүс нутгийн хурцадмал байдал нь дэлхийн нефтийн нийлүүлэлт, үнэд шууд нөлөөлж байна.", textEn:"A tanker sailing outbound through the Strait of Hormuz was struck by an unknown projectile, damaging its engine room, the United Kingdom Maritime Trade Operations agency said. The incident occurred about 6 nautical miles north of Khasab, Oman, at 1645 UTC on the evening of November 18.\n\nThe report does not identify the tanker or the origin of the projectile, and it is unclear whether the incident is linked to earlier attacks. The agency issued a maritime security warning to shipping.\n\nThe incident came as fighting intensified across the Gulf region. After the United States struck a missile launch site on Iran's Qeshm Island, Iran launched drone attacks on US bases in Kuwait and Bahrain, and the Houthi group fired missiles toward Saudi Arabia.\n\nIran has blockaded the Strait of Hormuz since the start of the war and targeted tankers passing through it; before the war, a quarter of the world's oil was shipped through the strait. Regional tensions are directly affecting global oil supplies and prices."},
  {id:11, cat:"delhii", title:"Украин Оросын хоёр нефть боловсруулах үйлдвэрийг онилж, Оросын боловсруулалт 45 хувиар буурчээ", titleEn:"Ukraine hits two Russian refineries as Russian refining falls 45 percent", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Altona%20oil%20refinery%202.jpg?width=760", text:"Украин өчигдөр буюу арваннэгдүгээр сарын 18-нд Оросын өмнөд хэсгийн хоёр нефть боловсруулах үйлдвэрт шинэ цохилт өгсөн тухай тус улсын албан тушаалтнууд мэдэгдлээ. Украины Жанжин штабын мэдээлснээр Краснодар хязгаар дахь Ильскийн нефть боловсруулах үйлдвэрийн агуулах савнууд, Афипскийн үйлдвэрийн боловсруулах хэсэгт цохилт өгсөн байна.\n\nХоёр үйлдвэр нь ням гарагийн шөнө ч мөн онилогдсон бөгөөд жилд нийт 95 сая баррель орчим нефть боловсруулж, Украины өмнөд болон зүүн фронт дахь Оросын цэргийг түлшээр хангадаг гэж мэдэгдсэн байна. Оросын албан тушаалтнууд бүс нутгийн хоёр аж үйлдвэрийн байгууламжид гал гарсан тухай мэдээлсэн боловч дэлгэрэнгүй мэдээлэл өгөөгүй байна.\n\nУкраины дроны довтолгооны улмаас Оросын нефть боловсруулах үйлдвэрүүдийн нийт боловсруулалтын хэмжээ аравдугаар сарын сүүлээс хойш 45 хувиар буурсан тухай салбарын хоёр эх сурвалж Ройтерс агентлагт мэдээллээ. Оросын 35 томоохон үйлдвэрийн 15-ынх нь үйл ажиллагаа тасалдсан буюу зогссон бөгөөд өдрийн боловсруулалт 700 мянган тонн гаруйгаас 400 мянган тонн орчим болж буурсан байна.\n\nҮүний зэрэгцээ Украины Ерөнхийлөгч Володимир Зеленский Крымийг Орост холбосон Керчийн гүүрийг гэмтээсэн дотооддоо үйлдвэрлэсэн зэвсгийн үр нөлөөг магтсан байна. Тэрбээр холын зайн дрон, пуужинг хэдэн долоо хоногийн турш бэлтгэсэн томоохон ажиллагаанд ашигласан гэж мэдэгдлээ. НҮБ-ын Хүний эрхийн хяналтын байгууллагын мэдээлснээр өнгөрсөн сард Украинд 372 энгийн иргэн амиа алдаж, 1981 хүн шархадсан нь 2025 оны аравдугаар сараас 95 хувиар их байна.", textEn:"Ukraine carried out new strikes on two oil refineries in southern Russia yesterday, November 18, Ukrainian officials said. Ukraine's General Staff said storage tanks were hit at the Ilsky refinery and a processing unit was struck at the Afipsky refinery, both in Russia's Krasnodar region.\n\nThe two refineries, which were also targeted on Sunday night, can process around 95 million barrels of oil a year and supply Russian forces on the front line in southern and eastern Ukraine, it said. Russian officials reported fires at two industrial facilities in the region but gave no details.\n\nUkrainian drone attacks have slashed Russian oil refineries' combined crude processing volumes by 45 percent since late October, two industry sources told Reuters. Operations at 15 of Russia's 35 major refineries have been disrupted or halted, and daily processing has fallen from more than 700,000 metric tons to around 400,000 metric tons.\n\nAt the same time, Ukrainian President Volodymyr Zelenskyy praised the effectiveness of domestically produced weapons that damaged the Kerch Bridge linking Russia to the occupied Crimean Peninsula. He said Ukraine's long-range drones and missiles were deployed in a large-scale attack prepared over weeks. The United Nations Human Rights Monitoring Mission in Ukraine said 372 civilians were killed and 1,981 injured last month — 95 percent more than in October 2025."},
  {id:12, cat:"delhii", title:"НАТО-гийн холбоотнууд Пентагоны бодлогын даргын Украины талаарх үгийг шүүмжиллээ", titleEn:"NATO allies rebuke Pentagon policy chief over Ukraine remarks", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Brussels-NATO%20headquarters.jpg?width=760", text:"АНУ-ын Батлан хамгаалах яамны бодлогын дарга Элбриж Колби мягмар гарагт НАТО-гийн холбоотнуудад Украины Оросын гүн дэх цохилтууд дайныг богиносгоогүй, Оросын давшилтыг удаашруулаагүй гэж мэдэгдсэний дараа холбоотнууд түүний үгийг шүүмжиллээ. Колби тусламжийг фронтын ажиллагаанд чиглүүлэхийг уриалсан байна.\n\nУкраины дроны довтолгооны улмаас Оросын нефть боловсруулах үйлдвэрүүдийн боловсруулалт аравдугаар сарын сүүлээс хойш 45 орчим хувиар буурч, 35 томоохон үйлдвэрийн 15 нь тасалдсан тухай Ройтерс агентлаг мэдээлсэн байна. Боловсруулалт буурсан нь Оросын АНУ-д дизель түлш экспортлох гэрээг биелүүлэх чадварт нөлөөлж болзошгүй гэж эх сурвалжууд тэмдэглэжээ.\n\nЕрөнхийлөгч Дональд Трамп Украинд Оросын нефть боловсруулах үйлдвэрүүд рүү цохилт өгөхөө зогсоохыг уриалж, эдгээр довтолгоо нь дэлхийн дизелийн хомсдолын шалтгаан болж байна гэж мэдэгдсэн байна. АНУ-ын Ерөнхийлөгч аравдугаар сарын 11-нд Орос, Украины хооронд «эрчим хүчний гал зогсоох» тохиролцоо зарласан ч түүнээс хойш дайн улам ширүүссэн байна.\n\nОросын тал ч Украины дэд бүтэц рүү цохилт өгсөөр байгаа бөгөөд Киев хотын Днепр мөрөн дээгүүрх гүүрнүүд пуужингийн цохилтод өртөж, хотын цахилгаан, ус, метроны сүлжээ тасалдсан гэж хотын дарга Виталий Кличко мэдэгдлээ. Энхийн хэлэлцээ үргэлжилж байгаа ч талууд бие биеийнхээ стратегийн байгууламж руу урт хугацааны цохилт өгсөөр байна.", textEn:"US Under Secretary of Defense for Policy Elbridge Colby told NATO allies on Tuesday that Ukraine's deep strikes inside Russia have not shortened the war or slowed Russia's advance, and his remarks were rebuked by allies. Colby urged that aid be directed to frontline operations.\n\nUkrainian drone attacks have cut Russian oil refineries' processing by about 45 percent since late October, disrupting 15 of the country's 35 major refineries, Reuters reported. Sources said reduced refining could hamper Russia's ability to deliver on a deal to export diesel to the United States.\n\nPresident Donald Trump has called on Ukraine to stop striking Russian refineries, blaming the attacks for a global diesel shortage. The US President announced an «energy ceasefire» between Russia and Ukraine on October 11, but the war has since intensified.\n\nRussia is also continuing to strike Ukrainian infrastructure: ballistic missiles hit bridges over the Dnipro River in Kyiv, disrupting the city's power, water and metro networks, according to Mayor Vitali Klitschko. Peace talks continue, but both sides keep launching long-range strikes on each other's strategic facilities."},
  {id:13, cat:"sport", title:"Тэрбишийн Ариунзаяа залуучуудын дэлхийн аварга боллоо", titleEn:"Terbish Ariunzaya becomes junior world champion", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/A%20judo%20competition%20%28FL61746686%29.jpg?width=760", text:"Узбекистан Улсын Ташкент хотноо болж буй жүдо бөхийн залуучуудын дэлхийн аварга шалгаруулах тэмцээнд Монголын тамирчин Тэрбишийн Ариунзаяа эмэгтэйчүүдийн 57 кг-ын жинд алтан медаль хүртэж, залуучуудын дэлхийн аварга боллоо. Тэрбээр өчигдөр буюу арваннэгдүгээр сарын 19-нд болсон алтан медалийн төлөөх барилдаанд Киргизийн Жанар Жолдошеванг ялсан байна.\n\nТ.Ариунзаяа шигшээ барилдааны 2 минут 21 секундэд эхлээд юко авч, дараа нь өрсөлдөгчөө иппонгоор шидэж, шийдэмгий ялалт байгуулсан байна. Энэ жинд эмэгтэйчүүдээс хамгийн олон буюу 44 тамирчин өрсөлдсөн бөгөөд манай жүдоч хэсгийн аваргын төлөө Венесуэлийн Одрис Пачеког, хагас шигшээд Азербайжаны Хадижа Гадашоваг ялсан байна.\n\nИнгэснээр 18 настай Т.Ариунзаяа өсвөр болон залуучуудын ангилалд хоёуланд нь түрүүлсэн анхны Монгол жүдоч болж байна. Тэрбээр 2024 онд Перугийн Лима хотноо болсон өсвөрийн дэлхийн аварга шалгаруулах тэмцээнд түрүүлж байсан билээ. Олон улсын жүдо бөхийн холбооноос түүнийг энэ өдрийн хамгийн том гэнэтийн бэлэг болсон гэж онцолсон байна.\n\nМонгол Улс залуучуудын дэлхийн аварга шалгаруулах тэмцээнээс өмнө нь хоёр алт, долоон мөнгө, найман хүрэл медаль хүртсэн түүхтэй. Гавьяат тамирчин Ө.Дүүрэнбаяр, олон улсын хэмжээний мастер Л.Сосорбарам нар алтан медаль хүртэж байсан бол энэ удаад Т.Ариунзаяа Монголын гурав дахь залуучуудын дэлхийн аварга боллоо. Тэмцээн арваннэгдүгээр сарын 22-ныг хүртэл үргэлжлэх бөгөөд Монголын 18 жүдоч өрсөлдөж байна.", textEn:"At the Junior World Judo Championships in Tashkent, Uzbekistan, Mongolia's Terbish Ariunzaya won the women's under-57-kilogram title and became junior world champion. She beat Zhanar Zholdosheva of Kyrgyzstan in the gold-medal bout yesterday, November 19.\n\nAriunzaya scored a yuko and then threw her opponent for ippon 2 minutes and 21 seconds into the final, winning decisively. The category drew the largest women's field, with 44 judoka, and she beat Odry Pacheco of Venezuela in the quarter-final and Khadija Gadashova of Azerbaijan in the semi-final.\n\nThe 18-year-old is now the first Mongolian judoka to win both the cadet and junior world titles. She won the cadet world title in Lima, Peru, in 2024. The International Judo Federation described her as the biggest surprise of the day.\n\nMongolia had previously won two gold, seven silver and eight bronze medals at the junior world championships. Honoured athlete U. Duurenbayar and international master L. Sosorbaram won the earlier golds, and Ariunzaya is now Mongolia's third junior world champion. The championships run until November 22, with 18 Mongolian judoka competing."},
  {id:14, cat:"sport", title:"Сүмо: Хошорюү Киришимаг ялж, Вакамотохарү 10 даваатай тэргүүлсээр байна", titleEn:"Sumo: Hoshoryu beats Kirishima as Wakamotoharu stays top with 10 wins", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Sumo%20wrestlers.jpg?width=760", text:"Японы Фүкүока хотод болж буй мэргэжлийн сүмогийн Кюүшү башёгийн 11 дэх өдөр буюу арваннэгдүгээр сарын 18-нд ёкозүна Хошорюү С.Бямбасүрэн озэки Киришима Б.Лхагвасүрэнг ёрикири мэхээр түлхэж гаргаж, 6 даваа, 5 унаатай боллоо. Хоёр Монгол бөхийн энэ тулаан башёгийн хамгийн их анхаарал татсан барилдааны нэг болсон бөгөөд Хошорюү дараалан хоёр дахь ялалтаа байгуулсан байна.\n\nЭнэхүү ялалтаар хоёр бөхийн хоорондын 13:13 тэнцээ эвдэрч, Хошорюү Киришимад дараалан гурван удаа ялагдсан цувралаа таслав. Киришима гурав дахь ялагдлаа хүлээж, 8 даваа, 3 унаатай болсон ч оны хамгийн олон ялалтын шагналыг дор хаяж хуваалцахаар баталгаажууллаа. Түүний 63 ялалтыг сүүлийн дөрвөн өдөрт хэн ч давах боломжгүй болсон бөгөөд энэ нь түүний хувьд 2023 оны 62 ялалтын дараах карьерийн хоёр дахь ийм амжилт юм.\n\n11 дэх өдрийн дараа маэгашира Вакамотохарү 10 даваа, 1 унаатай ганцаараа тэргүүлж, ёкозүна Оносато, сэкиваке Атамифүжи, маэгашира Кинбозан нар 9 даваа, 2 унаатайгаар нэг ялалтаар хоцорч байна. Монгол гаралтай ахмад бөх Тамаваши Б.Мөнх-Оргил 8 даваа, 3 унаатай болж, хожлын тоогоо баталгаажууллаа.\n\n12 дахь өдөр Хошорюү сэкиваке Фүжинокавагийн эсрэг барилдана. Хошорюү түүнд өмнө хоёр удаа ялагдаж байсан юм. Киришима харин ёкозүна Оносатотой тулна. Кюүшү башё арваннэгдүгээр сарын 22-нд өндөрлөх бөгөөд тэргүүлэгчдийн өрсөлдөөн сүүлийн өдрүүдэд улам ширүүсэх төлөвтэй байна.", textEn:"On day 11 of the Kyushu basho professional sumo tournament in Fukuoka, Japan, on November 18, yokozuna Hoshoryu S. Byambasuren beat ozeki Kirishima B. Lkhagvasuren by yorikiri, moving to 6 wins and 5 losses. The bout between the two Mongolian wrestlers was one of the most watched of the tournament, and it was Hoshoryu's second win in a row.\n\nThe victory broke the 13-13 head-to-head tie between the two and ended Hoshoryu's three-match losing streak against Kirishima. Kirishima took his third defeat and now stands at 8-3, but he has already secured at least a share of the prize for the most wins in the year. His 63 wins cannot be overtaken in the final four days, making this his second such achievement after 62 wins in 2023.\n\nAfter day 11, maegashira Wakamotoharu leads alone with 10 wins and 1 loss, one win ahead of yokozuna Onosato, sekiwake Atamifuji and maegashira Kinbozan, all on 9-2. Veteran Mongolian wrestler Tamawashi B. Munkh-Orgil secured a winning record at 8-3.\n\nOn day 12, Hoshoryu faces sekiwake Fujinokawa, who has beaten him twice before, while Kirishima meets yokozuna Onosato. The Kyushu basho ends on November 22, and the race at the top is set to intensify in the final days."},
  {id:15, cat:"soyol", title:"Хөгжмийн зохиолч Н.Баасандорж Монгол Улсын Гавьяат жүжигчин цол хүртэхээр болов", titleEn:"Composer N. Baasandorj to receive Honoured Artist title", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Morin%20khuur%20Mongoli%C3%AB.JPG?width=760", text:"Хөгжмийн зохиолч Норовын Баасандорж Монгол Улсын Гавьяат жүжигчин цол хүртэхээр боллоо. Баянхонгор аймгийн Гурванбулаг сумын харьяат, хөгжмийн зохиолч Н.Баасандорж нь сонсогчдын эчнээ мэдэх олон дууны хөгжмийг зохиосон уран бүтээлч билээ.\n\nТүүний зохиосон дуунуудаас «Хос шарга», «Зөөлөн зөөлөн замбуулин», «Зөн билэгтэй ээж», «Хосын хорвоо», «Энх мэндийн ерөөл» зэрэг бүтээлүүд олны хүртээл болж, Монголын дууны урлагт өөрийн байр сууриа эзэлсэн байна. Түүний дуунууд нь эх орон, ээж, хайр сэтгэл, энх тайвны сэдвийг хөнддөг бөгөөд олон үеийн сонсогчдын сэтгэлд хүрсэн юм.\n\nГавьяат жүжигчин цол нь Монгол Улсын урлагийн салбарын нэр хүндтэй шагналуудын нэг бөгөөд уран бүтээлчийн олон жилийн хөдөлмөр, урлагт оруулсан хувь нэмрийг үнэлж олгодог. Н.Баасандоржийн бүтээлүүд нь Монголын хөгжмийн өвийн нэг хэсэг болж, залуу уран бүтээлчдэд урам зориг өгч байна.\n\nБаянхонгор аймаг нь Монголын урлагийн олон нэрт зүтгэлтнийг төрүүлсэн нутаг бөгөөд тус аймгийн Хөгжимт драмын театр энэ сарыг «Монгол бахархал – Бүтээлч сар» болгон зарлаж, үндэсний урлагийн өв сан, уран бүтээлчдийнхээ сор бүтээлийг сэргээн тайзнаа толилуулж байгаа юм.", textEn:"Composer Norovyn Baasandorj is to receive the title of Honoured Artist of Mongolia. Baasandorj, a native of Gurvanbulag soum in Bayankhongor aimag, has composed the music for many songs familiar to Mongolian audiences.\n\nHis works include «Khos Sharga», «Zuulun Zuulun Zambuulin», «Zun Bilegtei Eej», «Khosyn Khorvoo» and «Enkh Mendiin Yuruul», which have found a wide audience and earned their place in Mongolian song. His songs take up themes of homeland, mothers, love and peace, and have touched generations of listeners.\n\nThe Honoured Artist title is one of Mongolia's most prestigious honours in the arts, awarded in recognition of many years of work and contribution to culture. Baasandorj's works have become part of Mongolia's musical heritage and an inspiration to young artists.\n\nBayankhongor aimag has produced many renowned Mongolian artists, and its Music Drama Theatre has declared this month «Mongolian Pride — Creative Month», reviving the finest works from its national art heritage and its artists' repertoire on stage."},
  {id:16, cat:"soyol", title:"Хүннүгийн хамгийн том булшнаас 413 олдвор илрүүлжээ", titleEn:"413 artefacts found in largest Xiongnu tomb", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Xiongnu%20sword%2C%20from%20a%20Xiongnu%20tomb%20in%20Xichagou%2C%20Xifeng%20County%2C%20Liaoning%20Province%20%28Han%20period%29.jpg?width=760", text:"Хэнтий аймгийн Баян-Адарга сумын Дуурлиг нарсны дурсгалт газрын 160 дугаар булшинд хийсэн Монгол, Солонгосын хамтарсан малтлага дуусч, нийт 413 олдвор илрүүлсэн тухай судалгааны үр дүнг БНСУ-ын Үндэсний музей энэ сарын 6-нд танилцууллаа. Уг булшийг Монгол Улсаас одоогоор илрүүлсэн Хүннүгийн үеийн хамгийн том булш гэж тодорхойлсон байна.\n\nБулш нь үүдэвчийн хамт 73 метр урт, 14.5 метр гүн бөгөөд есөн үе чулуун дараастай. Төв хэсэгт нь давхар модон бунхан дотор байрлуулсан авс илэрчээ. Малтлагаас Ромын эзэнт гүрний үед үйлдвэрлэсэн байж болзошгүй шилэн аяга, Хан улсын оршуулгын соёлын нөлөө бүхий 15 хаш эдлэл, Солонгосын хойгийн Лэлангийн булшнуудаас олдсон эдлэлтэй төстэй мөнгөн морины чимэглэл зэрэг олдвор гарсан байна.\n\nСудлаачид эдгээр олдворыг Хүннүгийн язгууртнууд Евразийн өргөн уудам нутаг дахь худалдаа, соёлын харилцаанд оролцож байсны чухал баримт гэж үзжээ. Булшийг МЭ I зууны сүүлээс II зуунд хамааруулж байгаа бөгөөд оршуулсан хүний хэн болохыг хараахан тогтоогоогүй байна.\n\nМалтлагыг БНСУ-ын Үндэсний музей, Монголын Шинжлэх ухааны академийн Археологийн хүрээлэн, Монголын Үндэсний музей хамтран 2023 оноос 2026 он хүртэл хийсэн юм. Судлаачид цаашид шилэн аяганы химийн найрлагыг шинжилж гарал үүслийг тодруулах, мөн авснаас илэрсэн шүд, үсээр ДНХ-ийн шинжилгээ хийж, оршуулсан хүний хүйс, насыг тогтоохоор төлөвлөж байна.", textEn:"A joint Mongolian-Korean excavation of tomb No. 160 at the Duurlig Nars site in Bayan-Adarga soum, Khentii aimag, has ended with 413 objects recovered, the National Museum of Korea said on November 6 when it presented the results. The tomb is described as the largest Xiongnu-era tomb found in Mongolia so far.\n\nThe tomb is 73 metres long including its entrance ramp and 14.5 metres deep, with nine layers of stone. At its centre, a coffin was found inside a double wooden chamber. The finds include a glass cup that may have been made in the Roman Empire, 15 jade objects influenced by Han Dynasty burial culture, and silver horse ornaments resembling objects from the Lelang tombs on the Korean peninsula.\n\nResearchers regard the finds as important evidence that Xiongnu nobles took part in trade and cultural exchange across the vast Eurasian region. The tomb is dated from the late 1st century to the 2nd century CE, and the identity of the person buried there has not yet been established.\n\nThe excavation was carried out jointly by the National Museum of Korea, the Institute of Archaeology of the Mongolian Academy of Sciences and the National Museum of Mongolia from 2023 to 2026. Researchers now plan to analyse the chemical composition of the glass cup to determine its origin, and to test DNA from teeth and hair found in the coffin to establish the occupant's sex and age."},
  {id:17, cat:"tech", title:"OpenAI-ийн хиймэл оюун AMD-ийн чипний загварыг 14 хувь хүртэл сайжруулав", titleEn:"OpenAI's AI improves AMD chip designs by up to 14 percent", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Integrated%20circuit%20on%20microchip.jpg?width=760", text:"OpenAI компани хиймэл оюуны загваруудаараа AMD компанийн чипний загварт гүйцэтгэл, эрчим хүчний хэрэглээ, талбайн хувьд 14 хувь хүртэл сайжруулалт хийсэн тухай өчигдөр буюу арваннэгдүгээр сарын 19-нд мэдэгдлээ. Тус компани энэ ахицыг «ойролцоогоор нэг жилийн ахицыг таван сараас бага хугацаанд гаргасан» гэж тодорхойлсон байна.\n\nСайжруулалтыг AMD-ийн тэргүүлэх график боловсруулах нэгж буюу GPU-ийн оюуны өмчид хийсэн бөгөөд зарим өөрчлөлтийг үйлдвэрлэлд илгээсэн загварт аль хэдийн оруулсан байна. Мөн AMD-ийн удахгүй гарах тэргүүлэх төв процессор буюу CPU-ийн гол хэсгүүдэд ганц оронтой хувийн сайжруулалт хийснийг AMD баталгаажуулсан байна.\n\nЗагварууд нь чипний хэлхээг тодорхойлдог SystemVerilog RTL кодыг дахин бичиж, Synopsys компанийн хэрэгслүүдийг ашиглан өөрчлөлтүүд нь анхны загварын үйлдлийг хадгалсан эсэхийг шалгаж, эрчим хүч, гүйцэтгэл, талбайд үзүүлэх нөлөөг үнэлсэн байна. GPT-6.2 Astra загвар нь PicoRV32, Ibex гэсэн хоёр нээлттэй RISC-V процессорын загвар дээр хийсэн 9881 удаагийн туршилтад хамгийн өндөр дундаж оноо авсан байна.\n\nOpenAI мөн өөрийн анхны Jalapeño нэртэй хиймэл оюун ухааны чипний загварт сайжруулалт хийсэн бөгөөд вектор нэгжийн талбайг 13 хувь, матриц нэгжийн талбайг 10 хувь бууруулсан байна. Тус компани Synopsys-тэй хамтран чипний инженерүүдийн багаж хэрэгслийг мэргэжилтэн шиг ашиглах GPT-Synopsys загварыг сургах болсон юм.", textEn:"OpenAI said yesterday, November 19, that its artificial intelligence models have improved AMD chip designs by up to 14 percent in performance, power and area. The company described the progress as «roughly a year of progress achieved in less than five months».\n\nThe improvements were made to AMD's flagship graphics processing unit intellectual property, and some of the changes have already been included in a design sent for manufacturing. AMD also confirmed single-digit percentage gains in key blocks of its upcoming flagship central processing unit.\n\nThe models rewrote SystemVerilog RTL code, which describes chip circuits, and used Synopsys tools to verify that the changes preserved the original design's behaviour and to assess their impact on power, performance and area. The GPT-6.2 Astra model recorded the highest average scores in 9,881 scored runs on two open-source RISC-V processor designs, PicoRV32 and Ibex.\n\nOpenAI also improved its first custom AI inference chip, Jalapeño, reducing standard-cell area by around 13 percent in its vector unit and 10 percent in its matrix unit. The company is partnering with Synopsys to train a new model, GPT-Synopsys, to use electronic design automation tools the way expert chip designers do."},
  {id:18, cat:"tech", title:"АНУ-ын чипний алсын хандалтын дүрэм өнөөдрөөс хэрэгжиж эхлэв", titleEn:"US remote-access chip rule takes effect today", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Intel%20factory%2C%20Kiryat%20Gat%20industry%20zone.jpg?width=760", text:"АНУ-ын Худалдааны яамны Аж үйлдвэр, аюулгүй байдлын товчооны буюу BIS-ийн хиймэл оюуны дэвшилтэт чипэнд алсаас хандахыг хязгаарлах түрэмгий эцсийн дүрэм өнөөдөр буюу арваннэгдүгээр сарын 19-нд Холбооны бүртгэлд нийтлэгдсэнээр хэрэгжиж эхэллээ. Дүрэм нь арваннэгдүгээр сарын 16-нд гарсан бөгөөд 90 хоногийн шилжилтийн хугацаатай байна.\n\nДүрмийн дагуу Хятад, Макао болон бусад D:5 бүлгийн улсад төвтэй компаниудад 12 сая нийт TPP-ээс дээш тооцоолох хүчин чадалд алсаас хандах боломж олгодог дата төвд зориулсан дэвшилтэт чип нийлүүлэхэд лиценз шаардлагатай болно. Мөн Индонез, Малайз, Сингапур, Тайланд, Бразил руу дэвшилтэт чип нийлүүлэхэд лицензийн шаардлага тавигдана.\n\nУг дүрэм нь Байдены засаг захиргааны үеийн хиймэл оюуны тархалтын дүрмийг албан ёсоор хүчингүй болгож байгаа бөгөөд олон нийтийн санал, шүүмжийг 2027 оны нэгдүгээр сарын 18-ны дотор хүлээн авна. Дүрэм нь түрээсийн замаар тойрч гарах боломжийг хааж байгаа юм: асуудал нь чип Хятад руу тээвэрлэгдэх эсэх бус, хэн түүнийг алсаас ашиглах вэ гэдэгт шилжсэн байна.\n\nNvidia компанийн түр гүйцэтгэх захирал Колетт Кресс тус компани Хятадад лицензтэй Hopper үеийн дата төвийн бүтээгдэхүүн нийлүүлэхээ зогсоосон гэж мэдэгдлээ. Nvidia аравдугаар сарын 25-наар дууссан улиралд Хятадад 2.4 тэрбум ам.долларын лицензтэй Hopper бүтээгдэхүүн борлуулсан байна. H200, H20 чипүүдийг 25 хувийн татвартайгаар нийлүүлэхийг зөвшөөрч байгаа бол илүү хүчирхэг Blackwell, Rubin GPU-г үндэсний аюулгүй байдлын шалтгаанаар хориглосон хэвээр байна.", textEn:"The US Commerce Department's Bureau of Industry and Security interim final rule restricting remote access to advanced artificial intelligence chips takes effect today, November 19, on its publication in the Federal Register. The rule was released on November 16 and carries a 90-day transition period.\n\nUnder the rule, a licence is required when advanced chips are destined for a data centre giving companies headquartered in China, Macau or other Country Group D:5 destinations remote access to more than 12 million aggregate TPP of compute. Licence requirements also apply to advanced-chip shipments to or within Indonesia, Malaysia, Singapore, Thailand and Brazil.\n\nThe rule formally rescinds the Biden-era AI Diffusion Rule, and public comments are due by January 18, 2027. It closes the rental workaround: the question is no longer whether chips ship to China, but who gets to use them remotely.\n\nNvidia interim chief executive Colette Kress said the company has stopped shipping licensed Hopper data-centre products to China. Nvidia sold 2.4 billion US dollars of licensed Hopper products to China in the quarter ended October 25. Its less powerful H200 and H20 chips may still be shipped with a 25 percent tariff, while the more powerful Blackwell and Rubin GPUs remain barred on national security grounds."},
];


function aTitle(a){ return LANG === "en" ? (a.titleEn || a.title) : a.title; }
function aTime(a){ return LANG === "en" ? (a.timeEn || a.time) : a.time; }
function aText(a){ if(a.text) return LANG === "en" ? (a.textEn || a.text) : a.text; return SAMPLE_TEXT[LANG][a.id === 1 ? "long" : "short"]; }
function aRegion(a){ return a.region ? ((REGIONS[LANG] && REGIONS[LANG][a.region]) || a.region) : ""; }

// ===== Ханш · Цаг агаар (өдөр бүр шинэчлэгдэнэ; цаг агаарыг Open-Meteo-гоос шууд татна) =====
const RATES = {date:"2026-11-20", items:[
  {code:"USD", mnt:3606.00, chg:1}, {code:"EUR", mnt:3960.29, chg:1}, {code:"JPY", mnt:22.58, chg:-1},
  {code:"CNY", mnt:541.02, chg:1}, {code:"KRW", mnt:2.71, chg:0}, {code:"RUB", mnt:43.84, chg:-1}, {code:"GBP", mnt:4743.87, chg:-1}
]};
let WEATHER = [
  {city:"Улаанбаатар", cityEn:"Ulaanbaatar", lat:47.9212, lon:106.9186, tz:"Asia/Ulaanbaatar", temp:-13, code:71},
  {city:"Токио", cityEn:"Tokyo", lat:35.6762, lon:139.6503, tz:"Asia/Tokyo", temp:14, code:80},
  {city:"Сөүл", cityEn:"Seoul", lat:37.5665, lon:126.978, tz:"Asia/Seoul", temp:-2, code:0},
  {city:"Бээжин", cityEn:"Beijing", lat:39.9042, lon:116.4074, tz:"Asia/Shanghai", temp:0, code:45},
  {city:"Москва", cityEn:"Moscow", lat:55.7558, lon:37.6173, tz:"Europe/Moscow", temp:5, code:45}
];
function wIcon(code){
  if(code === 0) return "☀️";
  if(code === 1) return "🌤️";
  if(code === 2) return "⛅";
  if(code === 3) return "☁️";
  if(code === 45 || code === 48) return "🌫️";
  if(code === 51 || code === 53 || code === 55 || code === 80) return "🌦️";
  if(code === 56 || code === 57 || code === 61 || code === 63 || code === 65 || code === 66 || code === 67 || code === 81 || code === 82) return "🌧️";
  if(code === 71 || code === 73 || code === 75 || code === 77 || code === 85 || code === 86) return "❄️";
  if(code >= 95) return "⛈️";
  return "🌡️";
}
function fmtRate(v){
  if(v >= 100) return Math.round(v).toLocaleString("en-US");
  return v.toFixed(2);
}
function renderData(){
  const parts = [];
  RATES.items.forEach(r=>{
    let arrow = "";
    if(r.chg > 0) arrow = ' <span class="up">▲</span>';
    else if(r.chg < 0) arrow = ' <span class="down">▼</span>';
    parts.push(`<span class="tk"><b>${r.code}</b> ${fmtRate(r.mnt)}₮${arrow}</span>`);
  });
  WEATHER.forEach(w=>{
    const name = LANG === "en" ? w.cityEn : w.city;
    const t = w.temp > 0 ? "+" + w.temp : "" + w.temp;
    parts.push(`<span class="tk">${wIcon(w.code)} ${name} ${t}°C</span>`);
  });
  const html = parts.join('<span style="color:#666">•</span>');
  const track = document.getElementById("tickerTrack");
  if(track) track.innerHTML = html + '<span style="color:#666">•</span>' + html + '<span style="color:#666">•</span>';
  const usd = RATES.items.find(r=>r.code === "USD");
  const ue = document.getElementById("usdText");
  if(ue && usd) ue.textContent = "USD: " + fmtRate(usd.mnt) + "₮";
  const wt = document.getElementById("weatherText");
  const ub = WEATHER[0];
  if(wt && ub) wt.textContent = wIcon(ub.code) + " " + (LANG === "en" ? ub.cityEn : ub.city) + " " + (ub.temp > 0 ? "+" + ub.temp : ub.temp) + "°C";
}
function refreshWeather(){
  WEATHER.forEach((w, idx)=>{
    const url = "https://api.open-meteo.com/v1/forecast?latitude=" + w.lat + "&longitude=" + w.lon + "&current=temperature_2m%2Cweather_code&timezone=" + encodeURIComponent(w.tz);
    fetch(url).then(r=>r.json()).then(d=>{
      if(d && d.current){ WEATHER[idx].temp = Math.round(d.current.temperature_2m); WEATHER[idx].code = d.current.weather_code; renderData(); }
    }).catch(()=>{});
  });
}

